package com.example.starter.orchestrator.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 条件谓词：仅当被引用节点达到期望状态时才允许本节点启动。
 * 引用关系构成隐式依赖边，参与循环检测。
 *
 * @param ref 被引用节点标识
 * @param expect 期望的被引用节点状态，如 HEALTHY
 */
public record ConditionSpec(
        @NotBlank String ref,
        @NotBlank String expect) {
}

package com.example.starter.orchestrator.dto;

import java.util.List;
import java.util.Map;

import jakarta.validation.Valid;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;

/**
 * 节点规格（合成数据，不触发真实进程）。
 *
 * @param key 节点标识，计划内唯一
 * @param params 节点参数
 * @param delayMillis 模拟启动延迟，单位毫秒
 * @param condition 条件谓词，可为 null
 * @param dependsOn 显式依赖节点标识列表
 * @param healthCheck 合成健康检查结果：PASS 或 FAIL
 * @param compensation 补偿/回滚动作名，可为 null
 */
public record NodeSpec(
        @NotBlank String key,
        Map<String, String> params,
        @Min(0) long delayMillis,
        @Valid ConditionSpec condition,
        List<String> dependsOn,
        @NotBlank @Pattern(regexp = "PASS|FAIL") String healthCheck,
        String compensation) {
}

package com.example.starter.orchestrator.dto;

import java.util.List;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.Size;

/**
 * 计划提交请求。同一 requestId 同参提交幂等，异参提交返回 409。
 *
 * @param planId 计划标识
 * @param version 计划版本
 * @param requestId 幂等请求标识
 * @param nodes 节点列表
 */
public record PlanSubmitRequest(
        @NotBlank @Size(max = 64) String planId,
        int version,
        @NotBlank @Size(max = 128) String requestId,
        @NotEmpty List<@Valid NodeSpec> nodes) {
}

