package com.example.starter.orchestrator;

/**
 * 同一 requestId 携带不同计划内容重复提交时抛出，映射 HTTP 409。
 */
public class PlanConflictException extends RuntimeException {

    public PlanConflictException(String message) {
        super(message);
    }
}

package com.example.starter.orchestrator;

import java.util.List;

/**
 * 执行前检测到显式依赖或条件引用导致的循环时抛出，映射 HTTP 400。
 * 携带完整循环依赖路径。
 */
public class CycleDependencyException extends RuntimeException {

    private final List<String> cyclePath;

    public CycleDependencyException(List<String> cyclePath) {
        super("检测到循环依赖: " + String.join(" -> ", cyclePath));
        this.cyclePath = List.copyOf(cyclePath);
    }

    public List<String> getCyclePath() {
        return cyclePath;
    }
}

package com.example.starter.orchestrator;

/**
 * 计划不存在时抛出，映射 HTTP 404。
 */
public class PlanNotFoundException extends RuntimeException {

    public PlanNotFoundException(String planId) {
        super("计划不存在: " + planId);
    }
}

package com.example.starter.orchestrator;

/**
 * 计划当前状态不允许目标操作（如对已终结计划再次执行）时抛出，映射 HTTP 409。
 */
public class PlanStateException extends RuntimeException {

    public PlanStateException(String message) {
        super(message);
    }
}

